    private void checkQueryGestures(EditText input)throws Exception{
        main(()->{input.setText("A10-1-1 TEST");input.requestFocus();input.setSelection(3);input.performClick();check(input.getSelectionStart()==3&&input.getSelectionEnd()==3,"Programmatic click must not force select-all");});
        test.waitForIdleSync();Thread.sleep(android.view.ViewConfiguration.getDoubleTapTimeout()+100);
        tapQuery(input,5);
        main(()->{int cursor=input.getSelectionStart();String before=input.getText().toString();check(cursor==input.getSelectionEnd()&&cursor>0&&cursor<before.length(),"Single tap must place a collapsed editing cursor");android.view.inputmethod.InputConnection keyboard=input.onCreateInputConnection(new android.view.inputmethod.EditorInfo());check(keyboard!=null&&keyboard.commitText("b",1),"Keyboard edit was rejected");check(input.getText().toString().equals(before.substring(0,cursor)+"B"+before.substring(cursor)),"Single-tap typing must insert uppercase text without replacing the query");});
        Thread.sleep(android.view.ViewConfiguration.getDoubleTapTimeout()+100);
        tapQuery(input,5);Thread.sleep(90);tapQuery(input,5);
        test.waitForIdleSync();
        main(()->check(input.getSelectionStart()==0&&input.getSelectionEnd()==input.length(),"Double tap must select the entire query, including spaces and punctuation"));
        Thread.sleep(android.view.ViewConfiguration.getDoubleTapTimeout()+100);tapQuery(input,4);
        main(()->check(input.getSelectionStart()==input.getSelectionEnd(),"A later single tap must resume normal cursor editing"));
        android.util.Log.i("KuguanQaInput","Single tap edits; double tap selects the whole query; uppercase typing retained");
    }
    private void tapQuery(EditText input,int offset)throws Exception{
        final long down=android.os.SystemClock.uptimeMillis();final float[] position=new float[2];
        main(()->{position[0]=input.getLayout().getPrimaryHorizontal(offset)+input.getTotalPaddingLeft()-input.getScrollX();position[1]=input.getHeight()/2f;android.view.MotionEvent event=android.view.MotionEvent.obtain(down,android.os.SystemClock.uptimeMillis(),android.view.MotionEvent.ACTION_DOWN,position[0],position[1],0);try{input.dispatchTouchEvent(event);}finally{event.recycle();}});
        Thread.sleep(45);
        main(()->{android.view.MotionEvent event=android.view.MotionEvent.obtain(down,android.os.SystemClock.uptimeMillis(),android.view.MotionEvent.ACTION_UP,position[0],position[1],0);try{input.dispatchTouchEvent(event);}finally{event.recycle();}});
    }
